        <form class="profile-search" @submit.prevent="search"><input v-model="query" aria-label="搜索人物" :disabled="saving" placeholder="搜索姓名或人物介绍" /><button type="submit" :disabled="saving">搜索</button></form>
        <div class="profile-filters"><label>性别<select v-model="gender" aria-label="人物性别筛选" :disabled="saving" @change="search"><option value="">全部性别</option><option value="men">男子</option><option value="women">女子</option></select></label><label>发布状态<select v-model="status" aria-label="人物发布状态" :disabled="saving" @change="search"><option value="">全部状态</option><option value="published">已发布</option><option value="draft">草稿</option><option value="archived">已下架</option></select></label></div>
        <div v-if="loading" class="profile-empty" role="status">正在读取人物档案…</div>
        <div v-else-if="!rows.length" class="profile-empty"><AdminIcon name="users" /><b>{{ query || gender || status ? '没有符合条件的人物' : '从第一份人物档案开始' }}</b><p>{{ query || gender || status ? '调整姓名、性别或发布状态后再试。' : '填写个人资料与文章，保存草稿后可继续完善。' }}</p></div>
        <button v-for="row in rows" v-else :key="row.id" type="button" class="profile-row" :class="{selected:draft?.id===row.id}" :disabled="saving || opening" @click="open(row)">
          <div class="profile-row-top"><span class="profile-initial">{{ row.name?.slice(0,1) || '人' }}</span><div><h4>{{ row.name }}</h4><span>{{ [genderLabel(row.gender),row.personalBest ? '全马 '+row.personalBest : ''].filter(Boolean).join(' · ') || '个人档案' }}</span></div><span class="profile-status" :class="row.status">{{ stateLabel(row) }}</span></div>
          <p>{{ row.bio || row.article?.lead || '尚未填写简介' }}</p><footer><span>{{ row.origin==='manual' ? '人工创建' : '采集档案' }}<template v-if="row.hasDraft && row.isPublic"> · 有未发布修改</template></span><span>编辑 <AdminIcon name="arrow" /></span></footer>
        </button>
        <div v-if="pages>1" class="profile-pager"><button type="button" :disabled="page<=1 || loading || saving" @click="turn(-1)">上一页</button><span>{{ page }} / {{ pages }}</span><button type="button" :disabled="page>=pages || loading || saving" @click="turn(1)">下一页</button></div>
      </section>
      <section v-if="draft" class="profile-editor" aria-label="人物编辑器">
        <header class="profile-editor-head"><div><p>{{ draft.id ? '编辑人物档案' : '创建人物档案' }}</p><h3>{{ draft.name || (isPacer ? '新建官兔' : '新建运动员') }}</h3><span>{{ publicDescription }}</span></div><button type="button" class="profile-close" aria-label="收起人物编辑器" :disabled="saving" @click="close">×</button></header>
        <nav class="profile-editor-tabs" aria-label="人物编辑内容"><button v-for="tab in tabs" :key="tab.id" type="button" :class="{on:editorTab===tab.id}" :aria-pressed="editorTab===tab.id" :disabled="saving" @click="editorTab=tab.id">{{ tab.label }}</button></nav>
        <section v-if="conflict" class="profile-conflict" role="alert"><b>这份档案已有更新，你的修改已保留。</b><p>先查看最新版本，再决定如何继续编辑。</p><div><button type="button" :disabled="saving || conflictLoading" @click="readLatest">{{ conflictLoading ? '读取中…' : '查看最新版本' }}</button><button v-if="latest" type="button" :disabled="saving" @click="continueWithLatest">保留我的修改，基于最新版本继续编辑</button></div><details v-if="latest" open><summary>最新版本 · {{ latest.name }}</summary><p v-if="latest.personalBest">最新全马 PB：{{ latest.personalBest }}</p><p v-if="latest.seasonBest">最新赛季最佳：{{ latest.seasonBest }}</p><p>{{ latest.article?.title }}</p><div class="profile-conflict-copy">{{ latest.article?.body || latest.bio || '最新版本暂无正文' }}</div></details></section>
        <form class="profile-form" @submit.prevent="save('published')">
          <fieldset :disabled="saving">
            <section v-show="editorTab==='base'" class="profile-form-section">
              <h4>基本资料</h4><div class="profile-pair"><label>姓名<input v-model="draft.name" maxlength="80" autocomplete="off" required /></label><label>性别<select v-model="draft.gender" required><option value="">请选择</option><option value="men">男子</option><option value="women">女子</option></select></label></div>
              <label>英文名<input v-model="draft.nameEn" maxlength="120" autocomplete="off" /></label>
              <div class="profile-avatar-field"><div class="profile-avatar-preview"><img v-if="avatarPreview && !imageBroken" :src="avatarPreview" :alt="draft.name || '人物头像预览'" @error="imageBroken=true" /><span v-else>{{ draft.name.slice(0,1) || '人' }}</span></div><label>头像图片地址<input v-model="draft.avatar" maxlength="2000" placeholder="https://… 或本站图片地址" /><small>使用可对应到本人的照片。</small><small v-if="imageBroken" class="profile-image-error">图片暂时无法显示，请检查地址。</small></label></div>
              <div class="profile-pair"><label>出生日期<input v-model="draft.birthDate" type="date" /></label><label>籍贯<input v-model="draft.placeOfBirth" maxlength="120" placeholder="省份或城市" /></label><label>所属队伍<input v-model="draft.team" maxlength="120" /></label><label>常驻城市<input v-model="draft.city" maxlength="120" /></label></div>
              <label>人物简介<textarea v-model="draft.bio" maxlength="1600" rows="4" placeholder="用于列表展示，用几句话介绍这位跑者。" /><small>{{ draft.bio.length }} / 1600</small></label>
              <div v-if="draft.origin==='collected' && draft.seasonRank" class="profile-collected-rank">自动采集排名：{{ draft.seasonYear }}赛季 {{ genderLabel(draft.gender) }}第 {{ draft.seasonRank }} 名<small>未人工修改的成绩与名次继续随采集更新。</small></div>
            </section>
            <section v-show="editorTab==='article'" class="profile-form-section">
              <h4>人物文章</h4><p class="profile-help">整理个人成长、重要比赛和职业转折。阅读页展示完整文章，不展示后台来源。</p>
              <label>文章标题<input v-model="draft.article.title" maxlength="160" placeholder="例如：从山路到马拉松赛场" /></label><label>文章导语<textarea v-model="draft.article.lead" rows="3" maxlength="1600" placeholder="用一段话引出这个人的跑步故事。" /></label><label>人物正文<textarea v-model="draft.article.body" rows="20" maxlength="40000" required placeholder="支持 Markdown：用 ## 小标题组织成长经历、比赛履历和人物故事。" /><small>{{ draft.article.body.length }} / 40000</small></label>
              <button class="profile-outline" type="button" @click="editorTab='preview'">预览文章</button>
            </section>
            <section v-show="editorTab==='career'" class="profile-form-section">
              <h4>{{ isPacer ? '个人成绩与配速履历' : '成绩与比赛履历' }}</h4>
              <div class="profile-pair"><label>全马个人最佳<input v-model="draft.personalBest" placeholder="2:30:00" maxlength="20" /></label><label>PB 比赛日期<input v-model="draft.eventDate" type="date" /></label></div><label>PB 赛事<input v-model="draft.eventName" maxlength="200" /></label><label>PB 比赛地点<input v-model="draft.eventVenue" maxlength="200" /></label>
              <template v-if="!isPacer"><h5>赛季成绩</h5><div class="profile-pair"><label>赛季年份<input v-model.number="draft.seasonYear" type="number" min="1900" max="2200" /></label><label>赛季最佳<input v-model="draft.seasonBest" maxlength="20" placeholder="2:30:00" /></label></div><label>赛季最佳赛事<input v-model="draft.seasonEventName" maxlength="200" /></label><label>赛季最佳比赛日期<input v-model="draft.seasonEventDate" type="date" /></label></template>
              <template v-if="isPacer">
                <div class="profile-repeat-heading"><h5>官方配速赛事</h5><button type="button" @click="addAssignment">添加配速赛事</button></div><p class="profile-help">填写已核实的 A 类赛事。公示入选与实际担任分开记录，只有“已担任”进入曾任官兔标签。</p>
                <article v-for="(entry,index) in draft.assignments" :key="entry._key" class="profile-repeat-card"><header><b>配速赛事 {{ index+1 }}</b><button type="button" :aria-label="'删除配速赛事 '+(index+1)" @click="draft.assignments.splice(index,1)">删除</button></header>
                  <label :for="'pacer-name-'+index">赛事名称 {{ index+1 }}</label><div class="profile-race-search"><input :id="'pacer-name-'+index" v-model="entry.raceName" :aria-label="'赛事名称 '+(index+1)" maxlength="200" @change="ensureRaceId(entry)" placeholder="输入赛事名称，可搜索已有赛历" /><button type="button" :disabled="raceSearching" @click="searchRaces(entry)">搜索赛事</button></div>
                  <div v-if="raceSearchKey===entry._key && raceHits.length" class="profile-race-results"><button v-for="race in raceHits" :key="race.id" type="button" @click="chooseRace(entry,race)"><b>{{ race.name }}</b><small>{{ race.raceDate }} · {{ race.city }}</small></button></div><p v-if="raceSearchKey===entry._key && raceSearchNotice" class="profile-help">{{ raceSearchNotice }}</p>
                  <div class="profile-pair"><label>比赛日期 {{ index+1 }}<input v-model="entry.raceDate" type="date" @change="ensureRaceId(entry)" /></label><label>赛事城市 {{ index+1 }}<input v-model="entry.city" maxlength="80" /></label><label>比赛距离 {{ index+1 }}<select v-model.number="entry.distanceKm"><option :value="42.195">全程马拉松 · 42.195 km</option><option :value="21.0975">半程马拉松 · 21.0975 km</option><option :value="10">10公里</option><option :value="5">5公里</option></select></label><label>目标完赛时间 {{ index+1 }}<input v-model="entry.targetTime" maxlength="20" placeholder="3:30:00" /></label><label>履历状态 {{ index+1 }}<select v-model="entry.status"><option value="provisional">入选公示</option><option value="published">已入选</option><option value="confirmed">已确认</option><option value="completed">已担任</option><option value="cancelled">已取消</option></select></label></div>
                  <p class="profile-assignment-pace">{{ entry.targetTime ? '目标配速约 '+targetPace(entry.targetTime,entry.distanceKm)+' / km' : '按所选比赛距离换算配速' }}<span>A 类赛事</span></p>
                  <details class="profile-race-identity"><summary>赛事关联信息</summary><label>赛事编号 {{ index+1 }}<input v-model="entry.raceId" maxlength="160" placeholder="从赛历选择或按赛事名称自动生成" @input="entry._autoRaceId=false" /></label><label>赛事年份 {{ index+1 }}<input v-model.number="entry.edition" type="number" min="1900" max="2200" placeholder="跟随比赛日期年份" @change="ensureRaceId(entry)" /></label></details>
                </article><p v-if="!draft.assignments.length" class="profile-help">还没有配速赛事，发布官兔前请至少添加一场。</p>
              </template>
              <div class="profile-repeat-heading"><h5>个人最好成绩</h5><button type="button" @click="addRecord">添加个人成绩</button></div>
              <article v-for="(entry,index) in draft.personalRecords" :key="entry._key" class="profile-repeat-card"><header><b>个人成绩 {{ index+1 }}</b><button type="button" :aria-label="'删除个人成绩 '+(index+1)" @click="draft.personalRecords.splice(index,1)">删除</button></header><div class="profile-pair"><label>项目 {{ index+1 }}<input v-model="entry.discipline" maxlength="80" placeholder="全程马拉松 / 半程马拉松" /></label><label>成绩 {{ index+1 }}<input v-model="entry.mark" maxlength="40" placeholder="2:30:00" /></label><label>成绩日期 {{ index+1 }}<input v-model="entry.date" type="date" /></label><label>比赛地点 {{ index+1 }}<input v-model="entry.venue" maxlength="200" /></label></div></article>
              <div class="profile-repeat-heading"><h5>代表性比赛</h5><button type="button" @click="addHighlight">添加比赛履历</button></div>
              <article v-for="(entry,index) in draft.careerHighlights" :key="entry._key" class="profile-repeat-card"><header><b>比赛履历 {{ index+1 }}</b><button type="button" :aria-label="'删除比赛履历 '+(index+1)" @click="draft.careerHighlights.splice(index,1)">删除</button></header><label>比赛名称 {{ index+1 }}<input v-model="entry.title" maxlength="200" /></label><div class="profile-pair"><label>比赛日期 {{ index+1 }}<input v-model="entry.date" type="date" /></label><label>比赛成绩 {{ index+1 }}<input v-model="entry.result" maxlength="40" /></label><label>比赛名次 {{ index+1 }}<input v-model="entry.position" maxlength="20" /></label></div></article>
            </section>
            <section v-show="editorTab==='preview'" class="profile-article-preview" aria-label="人物文章预览"><p>{{ isPacer ? '官兔档案' : '运动员档案' }} · {{ draft.name || '未填写姓名' }}</p><h2>{{ draft.article.title || draft.name || '未填写文章标题' }}</h2><div v-if="draft.article.lead" class="profile-preview-lead">{{ draft.article.lead }}</div><p v-if="!blocks.length" class="profile-help">写下人物正文后，在这里查看阅读效果。</p><p v-for="block in blocks" :key="block.i" :class="'preview-'+block.kind"><span v-if="block.mark">{{ block.mark }}</span><template v-for="run in block.runs" :key="run.j"><strong v-if="run.strong">{{ run.text }}</strong><template v-else>{{ run.text }}</template></template></p></section>
          </fieldset>
        </form>
        <details v-if="draft.id" class="profile-maintenance"><summary>采集资料与维护信息</summary><p>{{ draft.origin==='manual' ? '人工创建的个人档案' : '采集建立的个人档案，人工保存的修改会独立保留。' }}</p><p v-if="draft.updatedAt">最近维护：{{ date(draft.updatedAt) }}</p><p v-if="draft.verifiedAt">最近采集：{{ draft.verifiedAt }}</p><ul v-if="draft.sources?.length"><li v-for="(source,index) in draft.sources" :key="index"><a v-if="isHttps(source.url)" :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.title || '公开资料' }}</a><span v-else>{{ source.title || '公开资料' }}</span></li></ul><p class="profile-help">以上信息仅供后台维护，人物阅读页不展示资料来源。</p></details>
        <footer class="profile-savebar"><div><span class="profile-status" :class="draft.status">{{ stateLabel(draft) }}</span><button v-if="draft.id && draft.status!=='archived'" type="button" :disabled="saving" @click="archive">下架档案</button><router-link v-if="draft.id && draft.isPublic" :to="'/news/profiles/'+draft.id" target="_blank">查看前台 ↗</router-link></div><div><button type="button" :disabled="saving || conflict" @click="save('draft')">存为草稿</button><button type="button" class="profile-primary" :disabled="saving || conflict" @click="save('published')">{{ saving ? '保存中…' : draft.status==='published' ? '保存并发布' : '发布档案' }}</button></div></footer>
      </section>
      <section v-else class="profile-welcome"><span><AdminIcon name="users" /></span><h3>{{ isPacer ? '从个人出发，串起配速经历。' : '成绩之外，还有值得记录的故事。' }}</h3><p>选择一份档案继续完善，<br />或为一位跑者创建新的个人文章。</p><button type="button" :disabled="saving" @click="create">{{ isPacer ? '新建官兔' : '新建运动员' }} <AdminIcon name="plus" /></button><router-link :to="'/news?tab='+profileType" target="_blank">查看前台人物列表 ↗</router-link></section>
    </div>
  </section>
</template>

<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import AdminIcon from './AdminIcon.vue';
import {parseGuide} from '../../guide-md';
const props=defineProps({request:{type:Function,required:true},refreshKey:Number,sessionToken:String,profileType:{type:String,default:'athlete'}});
const isPacer=computed(()=>props.profileType==='pacer');
const tabs=computed(()=>[{id:'base',label:'基本资料'},{id:'article',label:'人物文章'},{id:'career',label:isPacer.value?'配速履历':'成绩履历'},{id:'preview',label:'文章预览'}]);
const rows=ref([]),total=ref(0),page=ref(1),pages=ref(1),query=ref(''),gender=ref(''),status=ref(''),draft=ref(null),loading=ref(false),opening=ref(false),saving=ref(false),error=ref(''),notice=ref(''),editorTab=ref('base'),imageBroken=ref(false),conflict=ref(false),conflictLoading=ref(false),latest=ref(null),raceSearching=ref(false),raceSearchKey=ref(''),raceHits=ref([]),raceSearchNotice=ref('');
const blocks=computed(()=>parseGuide(draft.value?.article?.body||''));
const avatarPreview=computed(()=>safeImage(draft.value?.avatar));
const publicDescription=computed(()=>!draft.value?.id?'新档案尚未发布':draft.value.isPublic?(draft.value.hasDraft?'前台保留已发布版本，当前修改尚未发布。':'当前已在前台公开。'):draft.value.status==='archived'?'档案已下架，发布后恢复展示。':'草稿仅在后台可见。');
let generation=0,listTicket=0,editorTicket=0,raceTicket=0,disposed=false,keyNumber=0,openedBaseline=null;
const localDrafts=new Map();
const clone=value=>JSON.parse(JSON.stringify(value));
const key=()=>String(++keyNumber);
const currentYear=()=>Number(new Intl.DateTimeFormat('en',{timeZone:'Asia/Shanghai',year:'numeric'}).format(new Date()));
function active(epoch){return !disposed&&epoch===generation&&props.sessionToken===sessionStorage.getItem('marathon_admin');}
function genderLabel(value){return value==='men'?'男子':value==='women'?'女子':'';}
function stateLabel(row){return row.status==='archived'?'已下架':row.status==='draft'?'草稿':'已发布';}
function date(value){const d=new Date(value);return Number.isFinite(d.getTime())?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Shanghai'}).format(d):'';}
function isHttps(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password;}catch{return false;}}
function safeImage(value){const v=String(value||'').trim();return isHttps(v)||(/^\/(?!\/)[^\s\\]*$/.test(v)&&!v.split('/').includes('..'))?v:'';}
function prepare(profile={}){const value={name:'',nameEn:'',gender:'',avatar:'',bio:'',birthDate:'',placeOfBirth:'',team:'',city:'',personalBest:'',eventDate:'',eventName:'',eventVenue:'',seasonBest:'',seasonYear:currentYear(),seasonEventDate:'',seasonEventName:'',personalRecords:[],careerHighlights:[],assignments:[],status:'draft',revision:0,baseVersion:'',hasDraft:false,isPublic:false,origin:'manual',...clone(profile)};value.article={title:'',lead:'',body:'',...(value.article||{})};for(const field of ['name','nameEn','gender','avatar','bio','birthDate','placeOfBirth','team','city','personalBest','eventDate','eventName','eventVenue','seasonBest','seasonEventDate','seasonEventName'])value[field]=String(value[field]||'');for(const field of ['personalRecords','careerHighlights','assignments'])value[field]=(value[field]||[]).map(row=>({...row,...(field==='assignments'?{distanceKm:Number(row.distanceKm)||42.195}:{}),_key:key()}));return value;}
function remember(){if(draft.value)localDrafts.set(draft.value.id||'new',{draft:clone(draft.value),baseline:clone(openedBaseline)});}
function resetConflict(){conflict.value=false;latest.value=null;conflictLoading.value=false;}
function resetRaceSearch(){raceTicket++;raceSearchKey.value='';raceHits.value=[];raceSearchNotice.value='';raceSearching.value=false;}
async function load(){const epoch=generation,ticket=++listTicket;if(!active(epoch))return;loading.value=true;error.value='';try{const data=await props.request('/admin/content/profiles?'+new URLSearchParams({type:props.profileType,page:String(page.value),pageSize:'12',q:query.value,gender:gender.value,status:status.value}));if(!active(epoch)||ticket!==listTicket)return;rows.value=data.profiles||[];total.value=data.total||0;pages.value=data.pages||1;page.value=data.page||1;}catch(e){if(active(epoch)&&ticket===listTicket)error.value=e.message||'人物档案暂时无法加载。';}finally{if(active(epoch)&&ticket===listTicket)loading.value=false;}}
function create(){if(saving.value)return;remember();editorTicket++;opening.value=false;const remembered=localDrafts.get('new');draft.value=prepare(remembered?.draft||{type:props.profileType});openedBaseline=remembered?clone(remembered.baseline):editableState(draft.value);editorTab.value='base';error.value='';notice.value=remembered?'已恢复未保存的新档案。':'';imageBroken.value=false;resetConflict();resetRaceSearch();}
async function open(row){if(saving.value)return;remember();const epoch=generation,ticket=++editorTicket;opening.value=true;error.value='';notice.value='';try{const data=await props.request('/admin/content/profiles/'+encodeURIComponent(row.id));if(!active(epoch)||ticket!==editorTicket)return;const remembered=localDrafts.get(row.id);draft.value=prepare(remembered?.draft||data.profile);openedBaseline=remembered?clone(remembered.baseline):editableState(draft.value);editorTab.value='base';if(remembered)notice.value='已恢复这份档案在当前页面中保留的修改。';imageBroken.value=false;resetConflict();resetRaceSearch();}catch(e){if(active(epoch)&&ticket===editorTicket)error.value=e.message||'这份人物档案暂时无法打开。';}finally{if(active(epoch)&&ticket===editorTicket)opening.value=false;}}
function close(){if(saving.value)return;remember();editorTicket++;opening.value=false;draft.value=null;notice.value='当前修改已保留在本页面，重新选择可继续编辑。';resetConflict();resetRaceSearch();}
function search(){if(saving.value)return;page.value=1;load();}
function turn(delta){if(saving.value||loading.value)return;page.value=Math.max(1,Math.min(pages.value,page.value+delta));load();}
function strip(rows,fields){return rows.map(row=>Object.fromEntries(fields.map(field=>[field,row[field]??''])));}
function editableState(v){const body={};for(const field of ['name','nameEn','gender','avatar','bio','birthDate','placeOfBirth','team','city','personalBest','eventDate','eventName','eventVenue','seasonBest','seasonEventDate','seasonEventName'])body[field]=v[field]||'';body.seasonYear=v.seasonYear!==''&&v.seasonYear!=null?Number(v.seasonYear):'';body.article={title:v.article.title||'',lead:v.article.lead||'',body:v.article.body||''};body.personalRecords=strip(v.personalRecords,['discipline','mark','date','venue']);body.careerHighlights=strip(v.careerHighlights,['date','title','result','position']);if(isPacer.value)body.assignments=v.assignments.map(row=>({raceId:row.raceId||'',raceName:row.raceName||'',raceDate:row.raceDate||'',city:row.city||'',raceGrade:'A',targetTime:row.targetTime||'',distanceKm:Number(row.distanceKm)||42.195,pace:targetPace(row.targetTime,row.distanceKm),status:row.status||'provisional',edition:Number(row.edition)||Number(row.raceDate?.slice(0,4))||currentYear()}));return body;}
function bodyFor(state){const v=draft.value;for(const assignment of v.assignments)ensureRaceId(assignment);const body={type:props.profileType,status:state,revision:v.revision,baseVersion:v.baseVersion,...editableState(v)};if(body.seasonYear==='')delete body.seasonYear;return body;}
async function save(state){if(saving.value||!draft.value||conflict.value)return;const epoch=generation,ticket=editorTicket;if(!active(epoch))return;const body=bodyFor(state),id=draft.value.id;saving.value=true;error.value='';notice.value='';try{const data=await props.request('/admin/content/profiles'+(id?'/'+encodeURIComponent(id):''),{method:id?'PUT':'POST',body:JSON.stringify(body)});if(!active(epoch)||ticket!==editorTicket)return;localDrafts.delete(id||'new');draft.value=prepare(data.profile);openedBaseline=editableState(draft.value);resetConflict();notice.value=state==='published'?'人物档案已发布，前台列表与详情已更新。':draft.value.isPublic?'草稿已保存，前台继续展示原已发布版本。':'草稿已保存，可继续补充资料。';await load();}catch(e){if(active(epoch)&&ticket===editorTicket){if(e.status===409){conflict.value=true;error.value='档案或采集资料已有更新，请先查看最新版本；本地修改仍保留。';}else error.value=e.message||'保存失败，当前修改仍保留，请稍后重试。';}}finally{if(active(epoch)&&ticket===editorTicket)saving.value=false;}}
async function archive(){if(saving.value||!draft.value?.id)return;const epoch=generation,ticket=editorTicket;if(!active(epoch))return;const local=clone(draft.value);saving.value=true;error.value='';notice.value='';try{const data=await props.request('/admin/content/profiles/'+encodeURIComponent(draft.value.id),{method:'DELETE',body:JSON.stringify({revision:draft.value.revision,baseVersion:draft.value.baseVersion})});if(!active(epoch)||ticket!==editorTicket)return;localDrafts.delete(draft.value.id);const saved=data.profile||{status:'archived',isPublic:false,revision:draft.value.revision+1};const metadata=Object.fromEntries(['status','isPublic','revision','baseVersion','hasDraft','updatedAt'].filter(field=>Object.hasOwn(saved,field)).map(field=>[field,saved[field]]));draft.value=prepare({...local,...metadata});resetConflict();notice.value='档案已下架，当前编辑内容仍保留，可存草稿或重新发布。';await load();}catch(e){if(active(epoch)&&ticket===editorTicket){if(e.status===409)conflict.value=true;error.value=e.status===409?'档案已有更新，请查看最新版本后再操作。':e.message||'下架失败，请重试。';}}finally{if(active(epoch)&&ticket===editorTicket)saving.value=false;}}
async function readLatest(){if(!draft.value?.id||conflictLoading.value)return;const epoch=generation,ticket=editorTicket;conflictLoading.value=true;try{const data=await props.request('/admin/content/profiles/'+encodeURIComponent(draft.value.id));if(active(epoch)&&ticket===editorTicket)latest.value=data.profile;}catch(e){if(active(epoch)&&ticket===editorTicket)error.value=e.message||'最新版本暂时无法读取，当前修改仍保留。';}finally{if(active(epoch)&&ticket===editorTicket)conflictLoading.value=false;}}
function continueWithLatest(){if(!latest.value||!draft.value)return;const local=editableState(draft.value),baseline=openedBaseline||{},fresh=prepare(latest.value),freshBaseline=editableState(fresh),same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);for(const field of Object.keys(local)){if(field==='article'){for(const part of ['title','lead','body'])if(!same(local.article[part],baseline.article?.[part]))fresh.article[part]=local.article[part];}else if(!same(local[field],baseline[field]))fresh[field]=Array.isArray(local[field])?local[field].map(row=>({...clone(row),_key:key()})):clone(local[field]);}draft.value=fresh;openedBaseline=freshBaseline;resetConflict();error.value='';notice.value='已保留你实际修改的内容，其他资料采用最新版本。请核对后保存。';}
function addRecord(){draft.value.personalRecords.push({discipline:'',mark:'',date:'',venue:'',_key:key()});}
function addHighlight(){draft.value.careerHighlights.push({date:'',title:'',result:'',position:'',_key:key()});}
function addAssignment(){draft.value.assignments.push({raceId:'',raceName:'',raceDate:'',city:'',raceGrade:'A',targetTime:'',distanceKm:42.195,pace:'',status:'provisional',edition:'',_key:key()});}
function raceHash(value){let number=2166136261;for(const char of value.normalize('NFKC').trim()){number^=char.codePointAt(0);number=Math.imul(number,16777619);}return(number>>>0).toString(36);}
function ensureRaceId(entry){if((entry.raceId&&!entry._autoRaceId)||!entry.raceName?.trim())return;const edition=Number(entry.edition)||Number(entry.raceDate?.slice(0,4))||currentYear();entry.raceId='editorial-race-'+edition+'-'+raceHash(entry.raceName);entry._autoRaceId=true;}
function targetPace(value,distanceKm=42.195){const m=String(value||'').match(/^(\d{1,2}):([0-5]\d)(?::([0-5]\d))?$/);if(!m)return '';const seconds=Math.round((Number(m[1])*3600+Number(m[2])*60+Number(m[3]||0))/(Number(distanceKm)||42.195));return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}
async function searchRaces(entry){if(saving.value)return;const text=entry.raceName.trim();resetRaceSearch();raceSearchKey.value=entry._key;if(!text){raceSearchNotice.value='先填写赛事名称，再搜索已有赛历。';return;}const epoch=generation,ticket=++raceTicket;raceSearching.value=true;try{const [people,catalog]=await Promise.allSettled([props.request('/content/profiles?type=pacer&pageSize=1&q='+encodeURIComponent(text)),props.request('/admin/races?when=all&q='+encodeURIComponent(text)+'&page=1&pageSize=6')]);if(!active(epoch)||ticket!==raceTicket)return;const needle=text.toLowerCase(),personData=people.status==='fulfilled'?people.value:{},catalogData=catalog.status==='fulfilled'?catalog.value:{};const existing=(personData.meta?.raceFilters||[]).filter(r=>String(r.name||'').toLowerCase().includes(needle)).slice(0,6).map(r=>{const assignment=(personData.profiles||[]).flatMap(p=>p.assignments||[]).find(a=>String(a.raceId)===String(r.id));return {...r,raceDate:assignment?.raceDate||'',city:assignment?.city||''};});raceHits.value=[...existing,...(catalogData.races||[]).filter(r=>!existing.some(a=>a.name===r.name))].slice(0,8);if(!raceHits.value.length)raceSearchNotice.value=people.status==='rejected'&&catalog.status==='rejected'?'赛事搜索暂时不可用，可先手动填写。':'赛历中未找到，可直接填写核实后的赛事名称与日期。';}catch(e){if(active(epoch)&&ticket===raceTicket)raceSearchNotice.value='赛事搜索暂时不可用，可先手动填写。';}finally{if(active(epoch)&&ticket===raceTicket)raceSearching.value=false;}}
function chooseRace(entry,race){entry.raceId=race.id;entry._autoRaceId=false;entry.raceName=race.name;entry.raceDate=race.raceDate||entry.raceDate||'';entry.city=race.city||entry.city||'';entry.edition=Number(race.edition)||Number(race.raceDate?.slice(0,4))||entry.edition;resetRaceSearch();}
watch(()=>draft.value?.avatar,()=>{imageBroken.value=false;});
watch(()=>props.refreshKey,()=>{if(!saving.value)load();});
watch(()=>props.sessionToken,()=>{generation++;listTicket++;editorTicket++;raceTicket++;rows.value=[];draft.value=null;localDrafts.clear();resetConflict();resetRaceSearch();saving.value=false;opening.value=false;loading.value=false;error.value='';notice.value='';if(props.sessionToken)load();});
onBeforeUnmount(()=>{disposed=true;generation++;listTicket++;editorTicket++;raceTicket++;localDrafts.clear();draft.value=null;rows.value=[];});
load();
</script>

